			function cntSum(){
			    var dsList = app.lookup("dsList");
			    var allSum = 0;
			    var sum01 = 0;
			    var sum02 = 0;
			    var sum03 = 0;
			    var sum04 = 0;
			    
			    for(var i = 0; i < dsList.getRowCount(); i++){
			        // 시도센터의 경우 시군구 지움
			        if(dsList.getValue(i, "INST_TYPE_SE_CD") == "5"){ // 시도센터(경기도학교밖청소년지원센터)
			            dsList.setValue(i, "SGG_CD", "");
			            dsList.setValue(i, "SGG_NM", "");
			        }
			        var dsListColName = dsList.getColumnNames();
			        for(var j = 0; j < dsListColName.length; j++){
			            if(dsListColName[j].indexOf("COL01") > -1){
			                sum01 += ValueUtil.fixNumber(dsList.getValue(i, dsListColName[j]));
			            }
			            if(dsListColName[j].indexOf("COL02") > -1){
			                sum02 += ValueUtil.fixNumber(dsList.getValue(i, dsListColName[j]));
			            }
			            if(dsListColName[j].indexOf("COL03") > -1){
			                sum03 += ValueUtil.fixNumber(dsList.getValue(i, dsListColName[j]));
			            }
			            if(dsListColName[j].indexOf("COL04") > -1){
			                sum04 += ValueUtil.fixNumber(dsList.getValue(i, dsListColName[j]));
			            }
			        }
			        allSum = sum01 + sum02 + sum03 + sum04;
			        
			        dsList.setValue(i, "SUM01", sum01);
			        dsList.setValue(i, "SUM02", sum02);
			        dsList.setValue(i, "SUM03", sum03);
			        dsList.setValue(i, "SUM04", sum04);
			        dsList.setValue(i, "TOT_SUM", allSum);
			        
			        allSum = 0;
			        sum01 = 0;
			        sum02 = 0;
			        sum03 = 0;
			        sum04 = 0;
			    }
			    util.Control.redraw(app, "grdList");
			}
